const input = $json.body ?? $json;
const channel = String(input.channel ?? '').toLowerCase();
const recipient = input.recipient ?? input.phone ?? input.email ?? null;
const message = String(input.message ?? '');
const dispatchId = input.dispatch_id ?? ('WF-263:' + (input.deal_id ?? input.lead_id ?? 'unknown') + ':' + (input.attempt_number ?? 1));
const idempotencyKey = input.idempotency_key ?? dispatchId + ':' + channel;
const provider = input.provider ?? 'configured_communication_provider';
const dnc = Boolean(input.dnc ?? input.do_not_contact);
const allowedChannel = channel === 'sms' || channel === 'email';
const recipientValid = typeof recipient === 'string' && recipient.trim().length > 0;
const messageValid = message.trim().length > 0;
const ready = allowedChannel && recipientValid && messageValid && !dnc;

let status = ready ? 'dispatch_ready' : dnc ? 'do_not_contact' : 'blocked';
let action = ready ? 'provider_dispatch_required' : dnc ? 'suppress_dispatch' : 'human_review';
let nextWorkflow = ready ? 'WF-264' : 'WF-126';

return [{ json: {
  ...input,
  workflow_id: 'WF-263',
  workflow_name: 'Communication Provider Dispatch → Delivery Receipt Controller',
  status,
  action,
  provider,
  channel,
  recipient,
  message,
  dispatch: {
    dispatch_id: dispatchId,
    idempotency_key: idempotencyKey,
    delivery_receipt_required: true,
    provider,
    provider_request: {
      channel,
      recipient,
      message,
      idempotency_key: idempotencyKey
    }
  },
  provider_runtime: {
    adapter: 'provider-agnostic',
    configured: Boolean(input.provider_configured ?? false),
    execution_mode: input.execution_mode ?? 'runtime_adapter',
    note: 'Provider execution is represented as a controlled dispatch contract; provider credentials must remain in runtime secrets, never GitHub.'
  },
  next_workflow: nextWorkflow,
  human_review_required: !ready && !dnc,
  contact_suppressed: dnc,
  crm_activity: {
    activity_type: 'communication_provider_dispatch',
    workflow_id: 'WF-263',
    status,
    action,
    dispatch_id: dispatchId,
    channel,
    provider
  }
} }];
